     1→// ============================================================================
     2→// FreeLang Planner 모듈 - 비용 기반 쿼리 실행 계획
     3→// ============================================================================
     4→// 목표: WHERE 절 기반으로 최적의 실행 경로 선택
     5→// 원리:
     6→//   1. 테이블 통계: row_count, 컬럼 min/max
     7→//   2. 비용 추정: 풀스캔 O(n), 인덱스 범위 O(log n + k)
     8→//   3. 계획 선택: 비용이 낮은 경로 선택
     9→// 구조:
    10→//   - TableStats, ExecPlan 구조체
    11→//   - 통계 수집 (stats_build, stats_update)
    12→//   - 계획 생성 (plan_query)
    13→//   - 계획 기반 실행 (execute_planned)
    14→// ============================================================================
    15→
    16→module planner {
    17→    // === 계획 타입 ===
    18→    const PLAN_FULL_SCAN:   i32 = 1;
    19→    const PLAN_INDEX_EQ:    i32 = 2;
    20→    const PLAN_INDEX_RANGE: i32 = 3;
    21→    const PLAN_INDEX_LIKE:  i32 = 4;
    22→
    23→    // === 제한값 ===
    24→    const MAX_COLS: i32 = 16;
    25→    const MAX_ROWS: i32 = 1024;
    26→
    27→    // === 에러 코드 ===
    28→    const PLAN_OK:           i32 = 0;
    29→    const PLAN_ERR_NO_STATS: i32 = 60;
    30→
    31→    // === 데이터 구조체 ===
    32→
    33→    // 테이블 통계 (통계 기반 비용 추정용)
    34→    struct TableStats {
    35→        row_count:    i32;
    36→        col_count:    i32;
    37→        col_min:      [i64];   // 각 컬럼별 MIN (INT만)
    38→        col_max:      [i64];   // 각 컬럼별 MAX (INT만)
    39→        col_null_cnt: [i32];   // NULL 수
    40→        col_type:     [i32];   // 컬럼 타입 (INT/STR/BOOL)
    41→    }
    42→
    43→    // 실행 계획
    44→    struct ExecPlan {
    45→        plan_type:  i32;   // PLAN_* 상수
    46→        index_col:  i32;   // 사용할 인덱스 컬럼 (-1 = 없음)
    47→        est_rows:   i32;   // 예상 결과 행 수
    48→        cost:       i32;   // 비용 추정치 (낮을수록 좋음)
    49→        error_code: i32;   // 에러 코드
    50→    }
    51→
    52→    // === 통계 생성 ===
    53→
    54→    // 테이블에서 통계 수집 (스캔 기반)
    55→    func stats_build(t: schema.Table) -> TableStats {
    56→        let stats = TableStats{
    57→            row_count:    t.row_count,
    58→            col_count:    t.schema.col_count,
    59→            col_min:      make([i64], MAX_COLS),
    60→            col_max:      make([i64], MAX_COLS),
    61→            col_null_cnt: make([i32], MAX_COLS),
    62→            col_type:     make([i32], MAX_COLS),
    63→        };
    64→
    65→        // 각 컬럼 타입 저장
    66→        let col_idx = 0;
    67→        for col_idx = 0; col_idx < stats.col_count; col_idx = col_idx + 1 {
    68→            stats.col_type[col_idx] = t.schema.col_defs[col_idx].col_type;
    69→        }
    70→
    71→        // INT 컬럼만 MIN/MAX 계산
    72→        for col_idx = 0; col_idx < stats.col_count; col_idx = col_idx + 1 {
    73→            if t.schema.col_defs[col_idx].col_type != schema.COL_TYPE_INT {
    74→                continue;
    75→            }
    76→
    77→            let found_first = false;
    78→            let row_idx = 0;
    79→            for row_idx = 0; row_idx < t.row_count; row_idx = row_idx + 1 {
    80→                if t.deleted_flags[row_idx] {
    81→                    stats.col_null_cnt[col_idx] = stats.col_null_cnt[col_idx] + 1;
    82→                    continue;
    83→                }
    84→
    85→                // SoA 레이아웃에서 값 읽기: [col_idx * MAX_ROWS + row_idx]
    86→                let soa_idx = col_idx * MAX_ROWS + row_idx;
    87→                let val = t.int_cols[soa_idx];
    88→
    89→                if !found_first {
    90→                    stats.col_min[col_idx] = val;
    91→                    stats.col_max[col_idx] = val;
    92→                    found_first = true;
    93→                } else {
    94→                    if val < stats.col_min[col_idx] {
    95→                        stats.col_min[col_idx] = val;
    96→                    }
    97→                    if val > stats.col_max[col_idx] {
    98→                        stats.col_max[col_idx] = val;
    99→                    }
   100→                }
   101→            }
   102→        }
   103→
   104→        return stats;
   105→    }
   106→
   107→    // === 계획 생성 (핵심 로직) ===
   108→
   109→    // WHERE 조건 기반 실행 계획 선택
   110→    func plan_query(q: query.Query, stats: TableStats, has_int_idx: bool, has_str_idx: bool) -> ExecPlan {
   111→        // 기본 계획: 풀스캔
   112→        let plan = ExecPlan{
   113→            plan_type:  PLAN_FULL_SCAN,
   114→            index_col:  -1,
   115→            est_rows:   stats.row_count,
   116→            cost:       stats.row_count,  // 비용 = 행 수
   117→            error_code: PLAN_OK,
   118→        };
   119→
   120→        // WHERE 절이 없으면 풀스캔
   121→        if q.where_count == 0 {
   122→            return plan;
   123→        }
   124→
   125→        // 복합 WHERE 절 (AND)은 풀스캔 (간단화)
   126→        if q.where_count > 1 {
   127→            return plan;
   128→        }
   129→
   130→        let where_clause = q.wheres[0];
   131→        let col_idx = where_clause.col_idx;
   132→
   133→        // 컬럼 범위 검증
   134→        if col_idx < 0 || col_idx >= stats.col_count {
   135→            plan.error_code = PLAN_ERR_NO_STATS;
   136→            return plan;
   137→        }
   138→
   139→        // ===== INT 인덱스 고려 =====
   140→        if has_int_idx && !where_clause.is_str {
   141→            // EQUALITY 비교 (==)
   142→            if where_clause.op == query.OP_EQ {
   143→                plan.plan_type = PLAN_INDEX_EQ;
   144→                plan.index_col = col_idx;
   145→                plan.est_rows = 1;
   146→                plan.cost = log_cost(stats.row_count) + 1;
   147→                return plan;
   148→            }
   149→
   150→            // RANGE 비교 (>, <, >=, <=)
   151→            if where_clause.op == query.OP_GT || where_clause.op == query.OP_LT ||
   152→               where_clause.op == query.OP_GE || where_clause.op == query.OP_LE {
   153→                let range_est = range_estimate(stats, col_idx, where_clause.op, where_clause.int_val);
   154→                plan.plan_type = PLAN_INDEX_RANGE;
   155→                plan.index_col = col_idx;
   156→                plan.est_rows = range_est;
   157→                plan.cost = log_cost(stats.row_count) + range_est;
   158→
   159→                // 범위가 작으면 인덱스 사용, 크면 풀스캔 (휴리스틱)
   160→                if plan.cost >= stats.row_count {
   161→                    plan.plan_type = PLAN_FULL_SCAN;
   162→                    plan.cost = stats.row_count;
   163→                }
   164→                return plan;
   165→            }
   166→        }
   167→
   168→        // ===== STR 인덱스 고려 =====
   169→        if has_str_idx && where_clause.is_str {
   170→            if where_clause.op == query.OP_LIKE {
   171→                // LIKE: 접두어 매칭 (B+Tree 범위 스캔)
   172→                let like_est = stats.row_count / 10;  // 휴리스틱: 전체의 1/10
   173→                plan.plan_type = PLAN_INDEX_LIKE;
   174→                plan.index_col = col_idx;
   175→                plan.est_rows = like_est;
   176→                plan.cost = log_cost(stats.row_count) + like_est;
   177→                return plan;
   178→            }
   179→        }
   180→
   181→        // 기본: 풀스캔
   182→        return plan;
   183→    }
   184→
   185→    // === 비용 추정 헬퍼 함수 ===
   186→
   187→    // log2(n) 근사 (비트 길이 이용)
   188→    @inline
   189→    func log_cost(n: i32) -> i32 {
   190→        if n <= 1 { return 0; }
   191→        if n <= 2 { return 1; }
   192→        if n <= 4 { return 2; }
   193→        if n <= 8 { return 3; }
   194→        if n <= 16 { return 4; }
   195→        if n <= 32 { return 5; }
   196→        if n <= 64 { return 6; }
   197→        if n <= 128 { return 7; }
   198→        if n <= 256 { return 8; }
   199→        if n <= 512 { return 9; }
   200→        if n <= 1024 { return 10; }
   201→        return 11;
   202→    }
   203→
   204→    // 범위 조건의 결과 행 수 추정
   205→    func range_estimate(stats: TableStats, col_idx: i32, op: i32, value: i64) -> i32 {
   206→        let col_min = stats.col_min[col_idx];
   207→        let col_max = stats.col_max[col_idx];
   208→        let col_range = col_max - col_min;
   209→
   210→        // 범위가 0이면 전체 반환
   211→        if col_range == 0 {
   212→            return stats.row_count;
   213→        }
   214→
   215→        // 조건별 추정 (균등 분포 가정)
   216→        if op == query.OP_GT {
   217→            // value < col <= col_max
   218→            if value >= col_max {
   219→                return 0;
   220→            }
   221→            let dist = (col_max - value) * 100 / col_range;
   222→            let est = (stats.row_count * dist) / 100;
   223→            if est < 1 { est = 1; }
   224→            return est;
   225→        }
   226→
   227→        if op == query.OP_LT {
   228→            // col_min <= col < value
   229→            if value <= col_min {
   230→                return 0;
   231→            }
   232→            let dist = (value - col_min) * 100 / col_range;
   233→            let est = (stats.row_count * dist) / 100;
   234→            if est < 1 { est = 1; }
   235→            return est;
   236→        }
   237→
   238→        if op == query.OP_GE {
   239→            // value <= col <= col_max
   240→            if value > col_max {
   241→                return 0;
   242→            }
   243→            let dist = (col_max - value) * 100 / col_range;
   244→            let est = (stats.row_count * dist) / 100 + 1;
   245→            if est < 1 { est = 1; }
   246→            return est;
   247→        }
   248→
   249→        if op == query.OP_LE {
   250→            // col_min <= col <= value
   251→            if value < col_min {
   252→                return 0;
   253→            }
   254→            let dist = (value - col_min) * 100 / col_range;
   255→            let est = (stats.row_count * dist) / 100 + 1;
   256→            if est < 1 { est = 1; }
   257→            return est;
   258→        }
   259→
   260→        // 미지의 연산자
   261→        return stats.row_count / 4;
   262→    }
   263→
   264→    // === 계획 기반 실행 ===
   265→
   266→    // 계획에 따라 인덱스 또는 풀스캔 사용
   267→    func execute_planned(t: schema.Table, q: query.Query,
   268→                        plan: ExecPlan, idx: index.BTreeIndex) -> query.QueryResult {
   269→
   270→        // PLAN_FULL_SCAN: 기존 query_execute 사용 (풀스캔)
   271→        if plan.plan_type == PLAN_FULL_SCAN {
   272→            return query.execute(t, q);
   273→        }
   274→
   275→        // PLAN_INDEX_EQ: 정확한 인덱스 탐색
   276→        if plan.plan_type == PLAN_INDEX_EQ {
   277→            let result = query.QueryResult{
   278→                row_indices: make([i32], 1024),
   279→                row_count:   0,
   280→                agg_value:   0,
   281→                error_code:  query.QUERY_OK,
   282→            };
   283→
   284→            let search_val = q.wheres[0].int_val;
   285→            let found_row_id, found = idx.index_search(search_val);
   286→
   287→            // 인덱스에서 찾은 row_id를 테이블 행 인덱스로 변환
   288→            if found {
   289→                let row_idx = 0;
   290→                for row_idx = 0; row_idx < t.row_count; row_idx = row_idx + 1 {
   291→                    if t.row_ids[row_idx] == found_row_id && !t.deleted_flags[row_idx] {
   292→                        result.row_indices[0] = row_idx;
   293→                        result.row_count = 1;
   294→                        break;
   295→                    }
   296→                }
   297→            }
   298→
   299→            return result;
   300→        }
   301→
   302→        // PLAN_INDEX_RANGE: 범위 탐색
   303→        if plan.plan_type == PLAN_INDEX_RANGE {
   304→            let result = query.QueryResult{
   305→                row_indices: make([i32], 1024),
   306→                row_count:   0,
   307→                agg_value:   0,
   308→                error_code:  query.QUERY_OK,
   309→            };
   310→
   311→            let min_val = q.wheres[0].int_val;
   312→            let op = q.wheres[0].op;
   313→            let max_val = min_val + 100;  // 범위 크기 (간단화)
   314→
   315→            // 범위 탐색: min_val ~ max_val 범위의 row_id 반환
   316→            // (index_range 함수는 index.fl에 구현되어 있다고 가정)
   317→            let i = 0;
   318→            for i = 0; i < t.row_count && result.row_count < 1024; i = i + 1 {
   319→                if t.deleted_flags[i] {
   320→                    continue;
   321→                }
   322→
   323→                let soa_idx = plan.index_col * MAX_ROWS + i;
   324→                let val = t.int_cols[soa_idx];
   325→
   326→                let matches = false;
   327→                if op == query.OP_GT {
   328→                    matches = val > min_val;
   329→                } else if op == query.OP_LT {
   330→                    matches = val < min_val;
   331→                } else if op == query.OP_GE {
   332→                    matches = val >= min_val;
   333→                } else if op == query.OP_LE {
   334→                    matches = val <= min_val;
   335→                }
   336→
   337→                if matches {
   338→                    result.row_indices[result.row_count] = i;
   339→                    result.row_count = result.row_count + 1;
   340→                }
   341→            }
   342→
   343→            return result;
   344→        }
   345→
   346→        // PLAN_INDEX_LIKE: 문자열 접두어 탐색
   347→        if plan.plan_type == PLAN_INDEX_LIKE {
   348→            let result = query.QueryResult{
   349→                row_indices: make([i32], 1024),
   350→                row_count:   0,
   351→                agg_value:   0,
   352→                error_code:  query.QUERY_OK,
   353→            };
   354→
   355→            // 문자열 인덱스 사용 (아직 미구현, 풀스캔 대신)
   356→            // 여기서는 간단화하여 풀스캔 로직 사용
   357→            let prefix = q.wheres[0].str_val;
   358→            let i = 0;
   359→            for i = 0; i < t.row_count && result.row_count < 1024; i = i + 1 {
   360→                if t.deleted_flags[i] {
   361→                    continue;
   362→                }
   363→
   364→                let soa_idx = plan.index_col * MAX_ROWS + i;
   365→                let str_val = t.str_cols[soa_idx];
   366→
   367→                // 접두어 매칭 (간단 구현)
   368→                if str_prefix_match(str_val, prefix) {
   369→                    result.row_indices[result.row_count] = i;
   370→                    result.row_count = result.row_count + 1;
   371→                }
   372→            }
   373→
   374→            return result;
   375→        }
   376→
   377→        // 기본: 풀스캔
   378→        return query.execute(t, q);
   379→    }
   380→
   381→    // === 문자열 유틸리티 ===
   382→
   383→    // 문자열 접두어 매칭
   384→    @inline
   385→    func str_prefix_match(str_val: string, prefix: string) -> bool {
   386→        let str_len = 0;
   387→        let i = 0;
   388→        for i = 0; i < 256; i = i + 1 {
   389→            if str_val[i:i+1] == "" {
   390→                str_len = i;
   391→                break;
   392→            }
   393→        }
   394→
   395→        let prefix_len = 0;
   396→        for i = 0; i < 256; i = i + 1 {
   397→            if prefix[i:i+1] == "" {
   398→                prefix_len = i;
   399→                break;
   400→            }
   401→        }
   402→
   403→        if prefix_len > str_len {
   404→            return false;
   405→        }
   406→
   407→        let j = 0;
   408→        for j = 0; j < prefix_len; j = j + 1 {
   409→            if str_val[j:j+1] != prefix[j:j+1] {
   410→                return false;
   411→            }
   412→        }
   413→
   414→        return true;
   415→    }
   416→
   417→    // === 계획 정보 출력 ===
   418→
   419→    // 계획 정보를 문자열로 변환 (디버깅)
   420→    func plan_to_str(plan: ExecPlan) -> string {
   421→        let type_str = "UNKNOWN";
   422→        if plan.plan_type == PLAN_FULL_SCAN {
   423→            type_str = "FULL_SCAN";
   424→        } else if plan.plan_type == PLAN_INDEX_EQ {
