// ============================================================================
// FreeLang Physical Plan Module - 논리 계획 → 물리 계획 변환
// ============================================================================
// 목표: Logical Plan(planner.ExecPlan) → Physical Plan(연산자 파이프라인)
// 원리:
//   1. 논리 계획(PLAN_FULL_SCAN, PLAN_INDEX_EQ, etc.)을 물리 연산자로 변환
//   2. 연산자 파이프라인: TABLE_SCAN → FILTER → SORT → LIMIT
//   3. 비용 추정: 각 연산자별 O(n) 또는 O(log n)
// 구조:
//   - 상수 정의 (연산자 타입, 에러 코드)
//   - PhysicalOp, PhysicalPlan 구조체
//   - 계획 생성 및 변환 함수
//   - 파이프라인 연결 및 비용 계산
// ============================================================================

module physical_plan {
    // === 연산자 타입 ===
    const PHYS_PLAN_TABLE_SCAN:  i32 = 1;   // 전체 테이블 스캔
    const PHYS_PLAN_INDEX_SCAN:  i32 = 2;   // 인덱스 기반 스캔
    const PHYS_PLAN_FILTER:      i32 = 3;   // WHERE 조건 필터
    const PHYS_PLAN_SORT:        i32 = 4;   // ORDER BY 정렬
    const PHYS_PLAN_LIMIT:       i32 = 5;   // LIMIT/OFFSET 페이징
    const PHYS_PLAN_AGGREGATE:   i32 = 6;   // 집계 함수 (COUNT/SUM/MAX/MIN)
    const PHYS_PLAN_NESTED_LOOP: i32 = 7;   // 중첩 루프 조인 (향후)

    // === 집계 연산자 타입 ===
    const PHYS_AGG_NONE:  i32 = 0;
    const PHYS_AGG_COUNT: i32 = 1;
    const PHYS_AGG_SUM:   i32 = 2;
    const PHYS_AGG_MAX:   i32 = 3;
    const PHYS_AGG_MIN:   i32 = 4;

    // === 에러 코드 ===
    const PHYS_OK:               i32 = 0;
    const PHYS_ERR_NOT_FOUND:    i32 = 90;
    const PHYS_ERR_INVALID_PLAN: i32 = 91;
    const PHYS_ERR_FULL:         i32 = 92;

    // === 제한값 ===
    const MAX_OPS: i32 = 32;   // 최대 연산자 수 (파이프라인 깊이)
    const MAX_COLS: i32 = 16;

    // === 데이터 구조체 ===

    // 물리 연산자 (파이프라인 노드)
    struct PhysicalOp {
        op_type:     i32;      // PHYS_PLAN_* 상수
        col_idx:     i32;      // 연산 컬럼 인덱스 (-1 = 무관)
        agg_type:    i32;      // PHYS_AGG_* (집계 연산자용)
        limit_count: i32;      // LIMIT 행 수 (-1 = 무제한)
        next_op:     i32;      // 파이프라인 다음 연산자 인덱스 (-1 = 끝)
        is_used:     bool;     // 슬롯 사용 여부
    }

    // 물리 계획 (연산자 파이프라인)
    struct PhysicalPlan {
        ops:         [PhysicalOp];    // 연산자 배열
        op_count:    i32;             // 사용 중인 연산자 수
        root_op_idx: i32;             // 루트 연산자 인덱스
    }

    // === 초기화 함수 ===

    // 새로운 물리 계획 생성
    func physical_plan_new() -> PhysicalPlan {
        let pp = PhysicalPlan{
            ops:         make([PhysicalOp], MAX_OPS),
            op_count:    0,
            root_op_idx: -1,
        };

        // 모든 슬롯을 미사용으로 초기화
        let i = 0;
        for i = 0; i < MAX_OPS; i = i + 1 {
            pp.ops[i].is_used = false;
            pp.ops[i].next_op = -1;
        }

        return pp;
    }

    // === 핵심 변환 함수 ===

    // 논리 계획(ExecPlan)을 물리 계획(PhysicalPlan)으로 변환
    func physical_plan_from_logical(ep: planner.ExecPlan) -> (PhysicalPlan, i32) {
        let pp = physical_plan_new();

        // 논리 계획 타입에 따라 연산자 파이프라인 구성
        if ep.plan_type == planner.PLAN_FULL_SCAN {
            // 풀스캔: TABLE_SCAN → FILTER → SORT → LIMIT
            let idx_table = pp_alloc_op_slot(&pp);
            if idx_table < 0 {
                return (pp, PHYS_ERR_FULL);
            }

            // TABLE_SCAN 연산자
            pp.ops[idx_table].op_type = PHYS_PLAN_TABLE_SCAN;
            pp.ops[idx_table].col_idx = -1;
            pp.ops[idx_table].is_used = true;
            pp.root_op_idx = idx_table;

            return (pp, PHYS_OK);
        }

        // INDEX_EQ: INDEX_SCAN → FILTER
        if ep.plan_type == planner.PLAN_INDEX_EQ {
            let idx_scan = pp_alloc_op_slot(&pp);
            if idx_scan < 0 {
                return (pp, PHYS_ERR_FULL);
            }

            // INDEX_SCAN 연산자
            pp.ops[idx_scan].op_type = PHYS_PLAN_INDEX_SCAN;
            pp.ops[idx_scan].col_idx = ep.index_col;
            pp.ops[idx_scan].is_used = true;
            pp.root_op_idx = idx_scan;

            return (pp, PHYS_OK);
        }

        // INDEX_RANGE: INDEX_SCAN → FILTER
        if ep.plan_type == planner.PLAN_INDEX_RANGE {
            let idx_scan = pp_alloc_op_slot(&pp);
            if idx_scan < 0 {
                return (pp, PHYS_ERR_FULL);
            }

            // INDEX_SCAN 연산자 (범위)
            pp.ops[idx_scan].op_type = PHYS_PLAN_INDEX_SCAN;
            pp.ops[idx_scan].col_idx = ep.index_col;
            pp.ops[idx_scan].is_used = true;
            pp.root_op_idx = idx_scan;

            return (pp, PHYS_OK);
        }

        // INDEX_LIKE: INDEX_SCAN (문자열 인덱스)
        if ep.plan_type == planner.PLAN_INDEX_LIKE {
            let idx_scan = pp_alloc_op_slot(&pp);
            if idx_scan < 0 {
                return (pp, PHYS_ERR_FULL);
            }

            pp.ops[idx_scan].op_type = PHYS_PLAN_INDEX_SCAN;
            pp.ops[idx_scan].col_idx = ep.index_col;
            pp.ops[idx_scan].is_used = true;
            pp.root_op_idx = idx_scan;

            return (pp, PHYS_OK);
        }

        // 미지의 논리 계획
        return (pp, PHYS_ERR_INVALID_PLAN);
    }

    // === 파이프라인 구성 함수 ===

    // 물리 계획에 새로운 연산자 추가
    func physical_plan_add_op(pp: *PhysicalPlan, op_type: i32, col_idx: i32, agg_type: i32, limit: i32) -> i32 {
        if pp.op_count >= MAX_OPS {
            return PHYS_ERR_FULL;
        }

        let op_idx = pp_alloc_op_slot(pp);
        if op_idx < 0 {
            return PHYS_ERR_FULL;
        }

        pp.ops[op_idx].op_type = op_type;
        pp.ops[op_idx].col_idx = col_idx;
        pp.ops[op_idx].agg_type = agg_type;
        pp.ops[op_idx].limit_count = limit;
        pp.ops[op_idx].is_used = true;

        return op_idx;
    }

    // 두 연산자를 파이프라인으로 연결 (from_idx → to_idx)
    func physical_plan_connect(pp: *PhysicalPlan, from_idx: i32, to_idx: i32) -> i32 {
        if from_idx < 0 || from_idx >= MAX_OPS || to_idx < 0 || to_idx >= MAX_OPS {
            return PHYS_ERR_INVALID_PLAN;
        }

        if !pp.ops[from_idx].is_used || !pp.ops[to_idx].is_used {
            return PHYS_ERR_NOT_FOUND;
        }

        pp.ops[from_idx].next_op = to_idx;
        return PHYS_OK;
    }

    // === 비용 추정 함수 ===

    // 물리 계획의 총 비용 계산
    func physical_plan_get_cost(pp: *PhysicalPlan) -> i64 {
        let total_cost = 0;
        let op_idx = pp.root_op_idx;
        let visited = 0;

        // 루트부터 시작하여 파이프라인 순회
        for visited = 0; visited < MAX_OPS && op_idx >= 0 && visited < pp.op_count; visited = visited + 1 {
            let op = pp.ops[op_idx];

            if op.op_type == PHYS_PLAN_TABLE_SCAN {
                // TABLE_SCAN: O(n)
                total_cost = total_cost + 1000;
            } else if op.op_type == PHYS_PLAN_INDEX_SCAN {
                // INDEX_SCAN: O(log n)
                total_cost = total_cost + 100;
            } else if op.op_type == PHYS_PLAN_FILTER {
                // FILTER: O(k) (k = 필터 조건 복잡도)
                total_cost = total_cost + 50;
            } else if op.op_type == PHYS_PLAN_SORT {
                // SORT: O(n log n)
                total_cost = total_cost + 500;
            } else if op.op_type == PHYS_PLAN_LIMIT {
                // LIMIT: O(1)
                total_cost = total_cost + 10;
            } else if op.op_type == PHYS_PLAN_AGGREGATE {
                // AGGREGATE: O(n)
                total_cost = total_cost + 200;
            }

            op_idx = op.next_op;
        }

        return total_cost;
    }

    // === 정보 조회 함수 ===

    // 물리 계획의 루트 연산자 인덱스 반환
    func physical_plan_get_root(pp: *PhysicalPlan) -> i32 {
        return pp.root_op_idx;
    }

    // 물리 계획의 통계 정보 출력 (디버깅용)
    func physical_plan_stats(pp: *PhysicalPlan) -> string {
        let stats_str = "PhysicalPlan(ops:";
        let i = 0;

        // 연산자 개수 계산
        for i = 0; i < MAX_OPS; i = i + 1 {
            if pp.ops[i].is_used {
                // 간단 포맷: op_count와 root_op_idx만 표시
            }
        }

        stats_str = stats_str + i32_to_str(pp.op_count);
        stats_str = stats_str + ", root:";
        stats_str = stats_str + i32_to_str(pp.root_op_idx);
        stats_str = stats_str + ")";

        return stats_str;
    }

    // === 헬퍼 함수 ===

    // 물리 계획에서 다음 사용 가능한 연산자 슬롯 할당
    @inline
    func pp_alloc_op_slot(pp: *PhysicalPlan) -> i32 {
        if pp.op_count >= MAX_OPS {
            return PHYS_ERR_FULL;
        }

        let op_idx = pp.op_count;
        pp.op_count = pp.op_count + 1;
        pp.ops[op_idx].is_used = false;
        pp.ops[op_idx].next_op = -1;

        return op_idx;
    }

    // 연산자 타입을 문자열로 변환 (디버깅)
    @inline
    func op_type_to_str(op_type: i32) -> string {
        if op_type == PHYS_PLAN_TABLE_SCAN {
            return "TABLE_SCAN";
        }
        if op_type == PHYS_PLAN_INDEX_SCAN {
            return "INDEX_SCAN";
        }
        if op_type == PHYS_PLAN_FILTER {
            return "FILTER";
        }
        if op_type == PHYS_PLAN_SORT {
            return "SORT";
        }
        if op_type == PHYS_PLAN_LIMIT {
            return "LIMIT";
        }
        if op_type == PHYS_PLAN_AGGREGATE {
            return "AGGREGATE";
        }
        if op_type == PHYS_PLAN_NESTED_LOOP {
            return "NESTED_LOOP";
        }
        return "UNKNOWN";
    }

    // 集計タイプを文字列に変換 (デバッグ用)
    @inline
    func agg_type_to_str(agg_type: i32) -> string {
        if agg_type == PHYS_AGG_COUNT {
            return "COUNT";
        }
        if agg_type == PHYS_AGG_SUM {
            return "SUM";
        }
        if agg_type == PHYS_AGG_MAX {
            return "MAX";
        }
        if agg_type == PHYS_AGG_MIN {
            return "MIN";
        }
        return "NONE";
    }

    // === 파이프라인 검증 함수 ===

    // 물리 계획의 파이프라인이 유효한지 검증
    func physical_plan_validate(pp: *PhysicalPlan) -> bool {
        if pp.root_op_idx < 0 {
            return false;
        }

        if pp.root_op_idx >= MAX_OPS || !pp.ops[pp.root_op_idx].is_used {
            return false;
        }

        // 사이클 감지: 파이프라인 순회 (최대 MAX_OPS번)
        let op_idx = pp.root_op_idx;
        let visited = 0;

        for visited = 0; visited < MAX_OPS && op_idx >= 0; visited = visited + 1 {
            if op_idx >= MAX_OPS {
                return false;
            }

            if !pp.ops[op_idx].is_used {
                return false;
            }

            op_idx = pp.ops[op_idx].next_op;
        }

        // 순환 그래프 감지 (MAX_OPS 이상 순회)
        if op_idx >= 0 {
            return false;
        }

        return true;
    }

    // === 연산자 통계 ===

    // 파이프라인의 연산자 깊이(길이) 반환
    func physical_plan_depth(pp: *PhysicalPlan) -> i32 {
        if pp.root_op_idx < 0 {
            return 0;
        }

        let op_idx = pp.root_op_idx;
        let depth = 0;

        for depth = 0; depth < MAX_OPS && op_idx >= 0; depth = depth + 1 {
            op_idx = pp.ops[op_idx].next_op;
        }

        return depth;
    }

    // 파이프라인에서 특정 연산자 타입이 포함되어 있는지 확인
    func physical_plan_has_op_type(pp: *PhysicalPlan, op_type: i32) -> bool {
        let op_idx = pp.root_op_idx;
        let visited = 0;

        for visited = 0; visited < MAX_OPS && op_idx >= 0; visited = visited + 1 {
            if pp.ops[op_idx].op_type == op_type {
                return true;
            }

            op_idx = pp.ops[op_idx].next_op;
        }

        return false;
    }

    // === 디버그 출력 함수 ===

    // 전체 파이프라인 상세 정보 출력
    func physical_plan_print_pipeline(pp: *PhysicalPlan) -> string {
        let result = "Pipeline: ";

        if pp.root_op_idx < 0 {
            result = result + "(empty)";
            return result;
        }

        let op_idx = pp.root_op_idx;
        let visited = 0;

        for visited = 0; visited < MAX_OPS && op_idx >= 0; visited = visited + 1 {
            let op = pp.ops[op_idx];
            result = result + op_type_to_str(op.op_type);

            if op.next_op >= 0 {
                result = result + " → ";
            }

            op_idx = op.next_op;
        }

        return result;
    }
}

// === 사용 예시 ===
//
// 1. 논리 계획에서 물리 계획 생성:
//    let ep = planner.plan_query(&q, &stats, true, false);
//    let pp, err = physical_plan_from_logical(ep);
//    if err != physical_plan.PHYS_OK {
//        // 에러 처리
