// ============================================================================
// FreeLang 물리 계획 통합 테스트 - Phase 9 (Physical Plan Engine)
// ============================================================================
// 범위: physical_plan 모듈 검증
// 시나리오:
//   1. 물리 계획 생성 및 초기화
//   2. 논리 계획 → 물리 계획 변환
//   3. 연산자 추가 및 파이프라인 연결
//   4. 비용 추정 및 통계 정보
//   5. 파이프라인 검증 및 통계
// ============================================================================

module physical_plan_test {
    // === 테스트 유틸리티 ===

    struct TestResult {
        name:    string;
        passed:  bool;
        message: string;
    }

    func assert_true(condition: bool, name: string) -> TestResult {
        return TestResult{
            name:    name,
            passed:  condition,
            message: if condition { "PASS" } else { "FAIL" },
        };
    }

    func assert_false(condition: bool, name: string) -> TestResult {
        return TestResult{
            name:    name,
            passed:  !condition,
            message: if !condition { "PASS" } else { "FAIL" },
        };
    }

    func assert_eq_i32(actual: i32, expected: i32, name: string) -> TestResult {
        let passed = actual == expected;
        return TestResult{
            name:    name,
            passed:  passed,
            message: if passed { "PASS" } else { "FAIL: expected " + i32_to_str(expected) + " got " + i32_to_str(actual) },
        };
    }

    func assert_eq_i64(actual: i64, expected: i64, name: string) -> TestResult {
        let passed = actual == expected;
        return TestResult{
            name:    name,
            passed:  passed,
            message: if passed { "PASS" } else { "FAIL: expected " + i64_to_str(expected) + " got " + i64_to_str(actual) },
        };
    }

    func print_result(r: TestResult) {
        let status = if r.passed { "[PASS]" } else { "[FAIL]" };
        print(status + " " + r.name + " - " + r.message);
    }

    // === 테스트 케이스 ===

    func test_physical_plan_new() -> TestResult {
        let pp = physical_plan.physical_plan_new();
        return assert_eq_i32(pp.op_count, 0, "test_physical_plan_new");
    }

    func test_physical_plan_root_init() -> TestResult {
        let pp = physical_plan.physical_plan_new();
        return assert_eq_i32(pp.root_op_idx, -1, "test_physical_plan_root_init");
    }

    func test_physical_plan_add_op() -> TestResult {
        let pp = physical_plan.physical_plan_new();
        let idx = physical_plan.physical_plan_add_op(&pp, physical_plan.PHYS_PLAN_TABLE_SCAN, -1, physical_plan.PHYS_AGG_NONE, -1);
        return assert_true(idx >= 0, "test_physical_plan_add_op");
    }

    func test_physical_plan_add_op_count() -> TestResult {
        let pp = physical_plan.physical_plan_new();
        physical_plan.physical_plan_add_op(&pp, physical_plan.PHYS_PLAN_TABLE_SCAN, -1, physical_plan.PHYS_AGG_NONE, -1);
        physical_plan.physical_plan_add_op(&pp, physical_plan.PHYS_PLAN_FILTER, 0, physical_plan.PHYS_AGG_NONE, -1);
        return assert_eq_i32(pp.op_count, 2, "test_physical_plan_add_op_count");
    }

    func test_physical_plan_add_op_full() -> TestResult {
        let pp = physical_plan.physical_plan_new();
        let i = 0;
        let last_idx = 0;

        // MAX_OPS까지 추가
        for i = 0; i < physical_plan.MAX_OPS; i = i + 1 {
            last_idx = physical_plan.physical_plan_add_op(&pp, physical_plan.PHYS_PLAN_TABLE_SCAN, -1, physical_plan.PHYS_AGG_NONE, -1);
        }

        // 초과 추가 시도
        let overflow_idx = physical_plan.physical_plan_add_op(&pp, physical_plan.PHYS_PLAN_TABLE_SCAN, -1, physical_plan.PHYS_AGG_NONE, -1);
        return assert_eq_i32(overflow_idx, physical_plan.PHYS_ERR_FULL, "test_physical_plan_add_op_full");
    }

    func test_physical_plan_connect() -> TestResult {
        let pp = physical_plan.physical_plan_new();
        let idx1 = physical_plan.physical_plan_add_op(&pp, physical_plan.PHYS_PLAN_TABLE_SCAN, -1, physical_plan.PHYS_AGG_NONE, -1);
        let idx2 = physical_plan.physical_plan_add_op(&pp, physical_plan.PHYS_PLAN_FILTER, 0, physical_plan.PHYS_AGG_NONE, -1);

        let result = physical_plan.physical_plan_connect(&pp, idx1, idx2);
        return assert_eq_i32(result, physical_plan.PHYS_OK, "test_physical_plan_connect");
    }

    func test_physical_plan_connect_pipeline() -> TestResult {
        let pp = physical_plan.physical_plan_new();
        let idx1 = physical_plan.physical_plan_add_op(&pp, physical_plan.PHYS_PLAN_TABLE_SCAN, -1, physical_plan.PHYS_AGG_NONE, -1);
        let idx2 = physical_plan.physical_plan_add_op(&pp, physical_plan.PHYS_PLAN_FILTER, 0, physical_plan.PHYS_AGG_NONE, -1);

        physical_plan.physical_plan_connect(&pp, idx1, idx2);

        // idx1 → idx2 연결 확인
        let passed = pp.ops[idx1].next_op == idx2;
        return assert_true(passed, "test_physical_plan_connect_pipeline");
    }

    func test_physical_plan_get_root() -> TestResult {
        let pp = physical_plan.physical_plan_new();
        let idx = physical_plan.physical_plan_add_op(&pp, physical_plan.PHYS_PLAN_TABLE_SCAN, -1, physical_plan.PHYS_AGG_NONE, -1);
        pp.root_op_idx = idx;

        let root = physical_plan.physical_plan_get_root(&pp);
        return assert_eq_i32(root, idx, "test_physical_plan_get_root");
    }

    func test_physical_plan_get_cost() -> TestResult {
        let pp = physical_plan.physical_plan_new();
        let idx = physical_plan.physical_plan_add_op(&pp, physical_plan.PHYS_PLAN_TABLE_SCAN, -1, physical_plan.PHYS_AGG_NONE, -1);
        pp.root_op_idx = idx;
        pp.ops[idx].is_used = true;

        let cost = physical_plan.physical_plan_get_cost(&pp);
        // TABLE_SCAN 비용: 1000
        return assert_true(cost > 0, "test_physical_plan_get_cost");
    }

    func test_physical_plan_validate_empty() -> TestResult {
        let pp = physical_plan.physical_plan_new();
        let valid = physical_plan.physical_plan_validate(&pp);
        return assert_false(valid, "test_physical_plan_validate_empty");
    }

    func test_physical_plan_validate_valid() -> TestResult {
        let pp = physical_plan.physical_plan_new();
        let idx = physical_plan.physical_plan_add_op(&pp, physical_plan.PHYS_PLAN_TABLE_SCAN, -1, physical_plan.PHYS_AGG_NONE, -1);
        pp.root_op_idx = idx;
        pp.ops[idx].is_used = true;

        let valid = physical_plan.physical_plan_validate(&pp);
        return assert_true(valid, "test_physical_plan_validate_valid");
    }

    func test_physical_plan_depth() -> TestResult {
        let pp = physical_plan.physical_plan_new();
        let idx1 = physical_plan.physical_plan_add_op(&pp, physical_plan.PHYS_PLAN_TABLE_SCAN, -1, physical_plan.PHYS_AGG_NONE, -1);
        let idx2 = physical_plan.physical_plan_add_op(&pp, physical_plan.PHYS_PLAN_FILTER, 0, physical_plan.PHYS_AGG_NONE, -1);
        let idx3 = physical_plan.physical_plan_add_op(&pp, physical_plan.PHYS_PLAN_SORT, 0, physical_plan.PHYS_AGG_NONE, -1);

        pp.root_op_idx = idx1;
        pp.ops[idx1].is_used = true;
        pp.ops[idx2].is_used = true;
        pp.ops[idx3].is_used = true;

        physical_plan.physical_plan_connect(&pp, idx1, idx2);
        physical_plan.physical_plan_connect(&pp, idx2, idx3);

        let depth = physical_plan.physical_plan_depth(&pp);
        return assert_eq_i32(depth, 3, "test_physical_plan_depth");
    }

    func test_physical_plan_has_op_type() -> TestResult {
        let pp = physical_plan.physical_plan_new();
        let idx = physical_plan.physical_plan_add_op(&pp, physical_plan.PHYS_PLAN_TABLE_SCAN, -1, physical_plan.PHYS_AGG_NONE, -1);
        pp.root_op_idx = idx;
